import{_ as t,o as a,c as d,a3 as o}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"源码概览","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"源码概览 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/design/overview"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/design/overview"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/design/overview"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/design/overview"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/design/overview"}]]},"headers":[],"relativePath":"zh/clice/design/overview.md","filePath":"zh/clice/design/overview.md","lastUpdated":1794738697000}'),c={name:"zh/clice/design/overview.md"};function n(r,e,s,i,l,p){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="源码概览" tabindex="-1">源码概览 <a class="header-anchor" href="#源码概览" aria-label="Permalink to &quot;源码概览&quot;">​</a></h1><p>clice 是一个 C++ 语言服务器，从架构起就围绕下面几个问题设计——早期的服务器不推倒重来就解决不了它们：</p><ul><li><strong>编译上下文。</strong> 编译、建立索引和回答请求的每一步都知道文件在哪个上下文中编译——使用哪条编译命令，头文件由哪个文件包含——用户也可以查看并切换它。参见<a href="./compilation-context">编译上下文</a>。</li><li><strong>多进程。</strong> 主进程保存状态，worker 进程运行 Clang，因此 Clang 发生崩溃或内存泄漏只会损失一个 worker，不会拖垮整个服务器。参见<a href="./multi-process">多进程架构</a>。</li><li><strong>统一的构建图。</strong> 每一项高开销产物——Preamble 的 PCH、模块的 PCM、已打开文件的 AST、为建立索引而编译的翻译单元——都是同一张图中的节点，由这张图统一复用构建产物、取消构建，并沿依赖关系传播失效。参见<a href="./task-graph">编译任务图</a>。</li><li><strong>协程。</strong> 异步工作基于 kotatsu 库以 C++20 协程编写，不用回调。</li></ul><h2 id="分层结构" tabindex="-1">分层结构 <a class="header-anchor" href="#分层结构" aria-label="Permalink to &quot;分层结构&quot;">​</a></h2><p><code>src/</code> 是按层划分的单个 C++20 模块，下表自底向上列出各层：每一层只导入排在它前面的层，唯独 <code>server</code> 和 <code>analysis</code> 并列位于 <code>project</code> 之上，且 <code>analysis</code> 不导入 <code>worker</code>。</p><table tabindex="0"><thead><tr><th>层</th><th>职责</th></tr></thead><tbody><tr><td><code>support</code></td><td>基础工具：日志、JSON、文本处理、模糊匹配、标记格式（markup）、失败记录。</td></tr><tr><td><code>vfs</code></td><td>clice 的磁盘视图：同一文件无论路径如何书写都具有唯一标识；所有判断文件是否变化的地方共用同一套新鲜度检查（先做 stat，再算内容哈希）；此外还包含磁盘缓存存储。</td></tr><tr><td><code>command</code></td><td>编译命令：从编译数据库解析一次，按规则编辑，再向每条命令的编译器查询以补全信息。参见<a href="./command-resolve">命令解析</a>。</td></tr><tr><td><code>syntax</code></td><td>无需 AST 的语法处理：词法分析器、头文件包含与模块依赖扫描、依赖图、包含路径解析。参见<a href="./dependency-scanning">依赖扫描</a>。</td></tr><tr><td><code>compile</code></td><td>统一接口背后的 Clang：单次编译的 AST、诊断、Token 与预处理指令，以及 clang-tidy。</td></tr><tr><td><code>semantic</code></td><td>基于 AST 的语义分析：每次编译遍历一次供所有功能查询、跨翻译单元一致的符号标识、<a href="./template-resolver">模板解析器</a>，以及文档注释。</td></tr><tr><td><code>index</code></td><td>符号索引：单翻译单元索引、按文件划分的分片（shard）、项目索引及其数据库，以及建立在它们之上的各类查询。参见<a href="./symbol-index">符号索引</a>。</td></tr><tr><td><code>feature</code></td><td>各项语言功能的响应结果，由 AST、索引或文档文本计算得出，自身不保存状态。</td></tr><tr><td><code>settings</code></td><td><code>clice.toml</code> 及叠加其上的编辑器设置，以及决定每个文件适用哪些配置的规则。</td></tr><tr><td><code>worker</code></td><td>worker 进程与进程池：任务分配、优先级、内存管理、崩溃处理和超时控制。</td></tr><tr><td><code>project</code></td><td>磁盘所呈现的项目状态：编译数据库、成员文件与编译命令、包含 PCH 和模块的构建图，以及项目索引。未保存的缓冲区从不改变项目对磁盘状态的描述。</td></tr><tr><td><code>server</code></td><td>语言服务器：已打开的文档、各文档归属的项目、当前由哪一方响应请求，以及与编辑器的连接。</td></tr><tr><td><code>analysis</code></td><td><code>clice analyze</code> 与 <code>clice modularize</code> 背后的分析逻辑。</td></tr><tr><td><code>driver</code></td><td><code>clice</code> 可执行文件的各个子命令。</td></tr></tbody></table><h2 id="数据流" tabindex="-1">数据流 <a class="header-anchor" href="#数据流" aria-label="Permalink to &quot;数据流&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>command (structured compile commands)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>project (task graph: PCH / PCM / AST / unit nodes) ──→ worker (processes)</span></span>
<span class="line"><span>    ↓ products</span></span>
<span class="line"><span>compile (drives Clang compilation)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>semantic (semantic map) ──→ index (unit index / shards / project index)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>feature (answers)</span></span></code></pre></div><p>服务器将每个请求路由到当前能够作答的数据源——最新的 AST，或在文件编译期间改用索引——收集该功能所需的输入并返回响应。编译由请求按需拉动，单凭一次编辑从不直接触发编译（参见<a href="./incremental-parse">增量编译</a>）。</p>`,9)])])}const g=t(c,[["render",n]]);export{m as __pageData,g as default};
